# A payment's split (billing/split.py): the store's fee and, with it, the
# publisher's share. Payments written before the split existed get it here,
# at the fee the portal is configured with when the migration runs - a sale
# and a renewal that percentage of their amount, a refund and a chargeback
# the proportion of the payment they take back.

from decimal import ROUND_HALF_UP, Decimal

from django.conf import settings
from django.db import migrations, models

CENT = Decimal("0.01")
ZERO = Decimal("0.00")


def split_earlier_payments(apps, schema_editor):
    Payment = apps.get_model("billing", "Payment")
    percent = settings.STORE_FEE_PERCENT
    by_order: dict[int, list] = {}
    for payment in Payment.objects.order_by("id"):
        by_order.setdefault(payment.order_id, []).append(payment)
    for payments in by_order.values():
        given_back: dict[int, tuple[Decimal, Decimal]] = {}   # the payment's id -> the amount and the fee already returned
        for payment in payments:
            if payment.kind in ("sale", "renewal"):
                payment.store_fee = (payment.amount * percent / 100).quantize(CENT, rounding=ROUND_HALF_UP)
            else:
                paid = [p for p in payments if p.kind in ("sale", "renewal") and p.id < payment.id]
                original = next((p for p in paid if payment.reverses and p.provider_transaction == payment.reverses), paid[-1] if paid else None)
                if original is None:
                    payment.store_fee = (payment.amount * percent / 100).quantize(CENT, rounding=ROUND_HALF_UP)
                else:
                    amount_before, fee_before = given_back.get(original.id, (ZERO, ZERO))
                    left = max(original.store_fee - fee_before, ZERO)
                    if original.amount <= 0 or amount_before + payment.amount >= original.amount:
                        payment.store_fee = left
                    else:
                        payment.store_fee = min((original.store_fee * payment.amount / original.amount).quantize(CENT, rounding=ROUND_HALF_UP), left)
                    given_back[original.id] = (amount_before + payment.amount, fee_before + payment.store_fee)
            payment.fee_percent = percent
            payment.save(update_fields=["fee_percent", "store_fee"])


